public class DocumentTest {

	@Test
	public void createShellValidUriTest() {
		Document doc = Document.createShell("http://www.example.com");
		assertNotNull(doc);
	}

	@Test
	public void createShellEmptyUriTest() {
		Document doc = Document.createShell("");
		assertNotNull(doc);
	}

	@Test
	public void locationTest() {
		Document doc = new Document("http://www.example.com");
		assertEquals("http://www.example.com", doc.location());
	}

	@Test
	public void connectionTest() {
		Document doc = new Document("http://www.example.com");
		Connection conn = doc.connection();
		assertNotNull(conn);
	}

	@Test
	public void documentTypeTest() {
		Document doc = new Document("http://www.example.com");
		DocumentType docType = doc.documentType();
		assertNull(docType);
	}

	@Test
	public void headTest() {
		Document doc = new Document("http://www.example.com");
		Element head = doc.head();
		assertNotNull(head);
	}

	@Test
	public void bodyTest() {
		Document doc = new Document("http://www.example.com");
		Element body = doc.body();
		assertNotNull(body);
	}

	@Test
	public void formsTest() {
		Document doc = new Document("http://www.example.com");
		List<FormElement> forms = doc.forms();
		assertEquals(0, forms.size());
	}

	@Test
	public void titleSetGetTest() {
		Document doc = new Document("http://www.example.com");
		doc.title("Test Title");
		assertEquals("Test Title", doc.title());
	}

	@Test
	public void createElementTest() {
		Document doc = new Document("http://www.example.com");
		Element element = doc.createElement("div");
		assertNotNull(element);
	}

	@Test
	public void charsetSetGetTest() {
		Document doc = new Document("http://www.example.com");
		Charset charset = Charset.forName("UTF-8");
		doc.charset(charset);
		assertEquals(charset, doc.charset());
	}

	@Test
	public void updateMetaCharsetElementSetGetTest() {
